+static class SeedSqlGenerator
+{
+    public static async Task GenerateAsync()
+    {
+        var repository = new MockRepository();
+
+        var players = await repository.GetPlayers();
+        var parties = await repository.GetParties();
+        var fields = await repository.GetPlayingFields();
+        var matches = await repository.GetMatchRecords();
+
+        var playerMap = new Dictionary<Guid, Player>();
+        var fieldMap = new Dictionary<Guid, PlayingField>();
+        var matchRecords = new List<MatchRecord>();
+        var matchPlayers = new List<MatchPlayer>();
+        var matchVotes = new List<MatchVote>();
+        var playerRatings = new List<PlayerRating>();
+        var preferredDates = new List<PreferredPlayingDate>();
+        var partyMembers = new List<PartyMember>();
+
+        foreach (var player in players)
+        {
+            AddPlayer(playerMap, player);
+        }
+
+        foreach (var party in parties)
+        {
+            AddPlayer(playerMap, party.PlayerCreated);
+            foreach (var member in party.Members)
+            {
+                AddPlayer(playerMap, member);
+                partyMembers.Add(new PartyMember(party.Id, member.Id));
+            }
+
+            preferredDates.AddRange(party.PreferredPlayingDates);
+        }
+
+        foreach (var field in fields)
+        {
+            AddField(fieldMap, field);
+        }
+
+        foreach (var match in matches)
+        {
+            matchRecords.Add(match);
+            AddField(fieldMap, match.PlayingField);
+
+            foreach (var entry in match.MatchPlayers)
+            {
+                matchPlayers.Add(entry);
+                AddPlayer(playerMap, entry.Player);
+
+                if (entry.PlayerRating != null)
+                {
+                    playerRatings.Add(entry.PlayerRating);
+                    AddPlayer(playerMap, entry.PlayerRating.PlayerGivingRating);
+                    AddPlayer(playerMap, entry.PlayerRating.PlayerReceivingRating);
+                }
+            }
+
+            foreach (var vote in match.MatchVotes)
+            {
+                matchVotes.Add(vote);
+                AddPlayer(playerMap, vote.Player);
+            }
+        }
+
+        var sql = BuildSql(
+            playerMap.Values.ToList(),
+            fieldMap.Values.ToList(),
+            parties,
+            partyMembers,
+            preferredDates,
+            matchRecords,
+            matchPlayers,
+            playerRatings,
+            matchVotes);
+
+        var root = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ".."));
+        var outputPath = Path.Combine(root, "seed-data.sql");
+        await File.WriteAllTextAsync(outputPath, sql, Encoding.UTF8);
+
+        Console.WriteLine($"Seed SQL written to: {outputPath}");
+    }
+
+    private static void AddPlayer(Dictionary<Guid, Player> map, Player player)
+    {
+        if (!map.ContainsKey(player.Id))
+        {
+            map[player.Id] = player;
+        }
+    }
+
+    private static void AddField(Dictionary<Guid, PlayingField> map, PlayingField field)
+    {
+        if (!map.ContainsKey(field.Id))
+        {
+            map[field.Id] = field;
+        }
+    }
+
+    private static string BuildSql(
+        List<Player> players,
+        List<PlayingField> fields,
+        List<Party> parties,
+        List<PartyMember> partyMembers,
+        List<PreferredPlayingDate> preferredDates,
+        List<MatchRecord> matchRecords,
+        List<MatchPlayer> matchPlayers,
+        List<PlayerRating> playerRatings,
+        List<MatchVote> matchVotes)
+    {
+        var sb = new StringBuilder(1024 * 64);
+
+        sb.AppendLine("SET FOREIGN_KEY_CHECKS=0;");
+        sb.AppendLine("START TRANSACTION;");
+
+        foreach (var player in players)
+        {
+            sb.AppendLine($"INSERT INTO `Players` (`Id`, `Username`, `Email`, `Bio`, `PreferredPosition`, `Age`, `ProfilePicture`) VALUES ({SqlGuid(player.Id)}, {SqlString(player.Username)}, {SqlString(player.Email)}, {SqlString(player.Bio)}, {SqlInt((int)player.PreferredPosition)}, {SqlNullableInt(player.Age)}, {SqlBytes(player.ProfilePicture)});");
+        }
+
+        foreach (var field in fields)
+        {
+            sb.AppendLine($"INSERT INTO `PlayingFields` (`Id`, `Name`, `Description`, `Longitude`, `Latitude`, `Image`, `ContactNumber`, `Status`, `IsOutdoor`, `SurfaceType`, `CountOfPlayedMatches`) VALUES ({SqlGuid(field.Id)}, {SqlString(field.Name)}, {SqlString(field.Description)}, {SqlDouble(field.Longitude)}, {SqlDouble(field.Latitude)}, {SqlBytes(field.Image)}, {SqlString(field.ContactNumber)}, {SqlInt((int)field.Status)}, {SqlBool(field.IsOutdoor)}, {SqlInt((int)field.SurfaceType)}, {SqlInt(field.CountOfPlayedMatches)});");
+        }
+
+        foreach (var party in parties)
+        {
+            sb.AppendLine($"INSERT INTO `Parties` (`Id`, `PlayerCreatedId`, `DateCreated`, `MaxMembers`, `PartyDescription`, `PreferredLocations`) VALUES ({SqlGuid(party.Id)}, {SqlGuid(party.PlayerCreatedId)}, {SqlDate(party.DateCreated)}, {SqlInt(party.MaxMembers)}, {SqlString(party.PartyDescription)}, {SqlString(party.PreferredLocations)});");
+        }
+
+        foreach (var link in partyMembers)
+        {
+            sb.AppendLine($"INSERT INTO `PartyMembers` (`PartyId`, `PlayerId`) VALUES ({SqlGuid(link.PartyId)}, {SqlGuid(link.PlayerId)});");
+        }
+
+        foreach (var date in preferredDates)
+        {
+            sb.AppendLine($"INSERT INTO `PreferredPlayingDates` (`Id`, `PartyId`, `Date`) VALUES ({SqlGuid(date.Id)}, {SqlGuid(date.PartyId)}, {SqlDate(date.Date)});");
+        }
+
+        foreach (var match in matchRecords)
+        {
+            sb.AppendLine($"INSERT INTO `MatchRecords` (`Id`, `WasMatchHeld`, `MatchHeld`, `PlayingFieldId`, `GoalsTeamA`, `GoalsTeamB`) VALUES ({SqlGuid(match.Id)}, {SqlBool(match.WasMatchHeld)}, {SqlDate(match.MatchHeld)}, {SqlGuid(match.PlayingFieldId)}, {SqlInt(match.GoalsTeamA)}, {SqlInt(match.GoalsTeamB)});");
+        }
+
+        foreach (var entry in matchPlayers)
+        {
+            sb.AppendLine($"INSERT INTO `MatchPlayers` (`Id`, `PlayerId`, `Team`, `MatchRecordId`, `Goals`, `Assists`) VALUES ({SqlGuid(entry.Id)}, {SqlGuid(entry.PlayerId)}, {SqlInt((int)entry.Team)}, {SqlGuid(entry.MatchRecordId)}, {SqlInt(entry.Goals)}, {SqlInt(entry.Assists)});");
+        }
+
+        foreach (var rating in playerRatings)
+        {
+            sb.AppendLine($"INSERT INTO `PlayerRatings` (`Id`, `MatchPlayerId`, `PlayerGivingRatingId`, `PlayerReceivingRatingId`, `Rating`) VALUES ({SqlGuid(rating.Id)}, {SqlGuid(rating.MatchPlayerId)}, {SqlGuid(rating.PlayerGivingRatingId)}, {SqlGuid(rating.PlayerReceivingRatingId)}, {SqlInt(rating.Rating)});");
+        }
+
+        foreach (var vote in matchVotes)
+        {
+            sb.AppendLine($"INSERT INTO `MatchVotes` (`Id`, `MatchRecordId`, `PlayerId`, `VotedHeld`) VALUES ({SqlGuid(vote.Id)}, {SqlGuid(vote.MatchRecordId)}, {SqlGuid(vote.PlayerId)}, {SqlBool(vote.VotedHeld)});");
+        }
+
+        sb.AppendLine("COMMIT;");
+        sb.AppendLine("SET FOREIGN_KEY_CHECKS=1;");
+
+        return sb.ToString();
+    }
+
+    private static string SqlGuid(Guid value) => $"'{value}'";
+
+    private static string SqlString(string value)
+        => $"'{value.Replace("'", "''")}'";
+
+    private static string SqlNullableInt(int? value)
+        => value.HasValue ? value.Value.ToString(CultureInfo.InvariantCulture) : "NULL";
+
+    private static string SqlInt(int value)
+        => value.ToString(CultureInfo.InvariantCulture);
+
+    private static string SqlDouble(double value)
+        => value.ToString(CultureInfo.InvariantCulture);
+
+    private static string SqlBool(bool value)
+        => value ? "1" : "0";
+
+    private static string SqlDate(DateTime value)
+        => $"'{value.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)}'";
+
+    private static string SqlBytes(byte[]? bytes)
+    {
+        if (bytes == null)
+        {
+            return "NULL";
+        }
+
+        if (bytes.Length == 0)
+        {
+            return "x''";
+        }
+
+        var sb = new StringBuilder(bytes.Length * 2);
+        foreach (var b in bytes)
+        {
+            sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
+        }
+
+        return $"x'{sb}'";
+    }
+
+    private sealed record PartyMember(Guid PartyId, Guid PlayerId);
+}
